from contextlib import contextmanager

@contextmanager
def tag(name):
    print("<" + name + ">")
    try:
        yield
    finally:
        print("</" + name + ">")

try:
    with tag("b"):
        print("text")
        1 / 0
except ZeroDivisionError:
    print("error")

