def twice(func):
    def wrapper(*args):
        func(*args)
        return func(*args)
    return wrapper

@twice
def hello(name):
    print("hi", name)

hello("Bo")

def deco(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

@deco
def add(a, b):
    """Add."""
    return a + b

print(add.__name__)

